//! The conformance goldens (`docs/loom-reinstall.md` §1.3) — generated by
//! `scripts/goldens.ts`, checked for drift by `golden.test.ts`, copied to
//! the Godot project by `scripts/sync.ts`. Per map:
//!
//! - `<name>.walls.json`  — `buildWalls(house)`.
//! - `<name>.routes.json` — `[{from, to, path}]`, the queries stored with
//!   their answers.
//! - `<name>.locate.json` — `[{p, floor, room, height, standable}]`;
//!   `height` is `heightAt([x, z], y)`, `standable` is `standable(p)` (the
//!   remap re-seat rule — queries include every solid prop's base).
//!
//! A map with a king prop also gets (C2, the shared King):
//!
//! - `<name>.king.json`   — `[{king, feet, yaw, reach, slack}]`: `kingReach`
//!   plain and with `KING_HIT_SLACK` (the server's).
//! - `<name>.fallen.json` — `[{from, to, path}]`: the route queries again,
//!   with every king fallen (`route(…, {fallen})`: his doors open).
//!
//! Every number is rounded to 1 mm, queries included (answers are computed
//! from the rounded queries). One JSON value per line, for readable diffs.

import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import {
  KING_HIT_SLACK,
  breakpoints,
  kingProps,
  kingReach,
  heightAt,
  locate,
  propSolid,
  standable,
  mm,
  pointInPolyStrict,
  pointInRect,
  portals,
  route,
  stairLevels,
  validateHouse,
  buildWalls,
} from "../src/index.ts";
import type { HouseMap, Room, Vec2, Vec3 } from "../src/index.ts";

export const ROOT = join(import.meta.dirname, "..");
export const FIXTURES = join(ROOT, "test", "fixtures");
export const GOLDEN = join(ROOT, "test", "golden");
/** The show's house map (the default every server / game falls back to). */
export const SHOW_HOUSE = join(ROOT, "..", "core", "examples", "trapped-in-the-internet", "house.json");
/** Its rain variant (the Internet in the shed, not the tent) — not a golden; checked by the show + route suites. */
export const SHOW_SHED_HOUSE = join(ROOT, "..", "core", "examples", "trapped-in-the-internet", "house.shed.json");
/**
 * The show's map as it stood before the real floor plan (wave 2: two floors,
 * the tent; `two-floor.shed.json` is its shed variant), frozen as the suites'
 * realistic many-room fixture: the mechanics tests pin its coordinates, so
 * they must not move with every edit to the live map. Not a golden.
 */
export const TWO_FLOOR_HOUSE = join(ROOT, "test", "maps", "two-floor.json");
export const TWO_FLOOR_SHED_HOUSE = join(ROOT, "test", "maps", "two-floor.shed.json");
/** The Godot project's copies (`pnpm --filter @loom/house sync`). */
export const VR_HOUSE = join(ROOT, "..", "reinstall", "vr", "house", "house.json");
export const VR_GOLDEN = join(ROOT, "..", "reinstall", "vr", "test", "golden");

/** Parse + validate a map file; throws with the problems when invalid. */
export function loadHouse(path: string): HouseMap {
  const v = validateHouse(JSON.parse(readFileSync(path, "utf8")));
  if (!v.ok || !v.house) throw new Error(`${path}: ${v.problems.join("; ")}`);
  return v.house;
}

export function fixture(name: string): HouseMap {
  return loadHouse(join(FIXTURES, `${name}.json`));
}

/** Every golden map: the fixtures (by file name) + "show". */
export function goldenMaps(): { name: string; house: HouseMap }[] {
  const names = readdirSync(FIXTURES)
    .filter((f) => f.endsWith(".json"))
    .map((f) => f.slice(0, -5))
    .sort();
  return [...names.map((name) => ({ name, house: fixture(name) })), { name: "show", house: loadHouse(SHOW_HOUSE) }];
}

const round3 = (p: readonly number[]): Vec3 => [mm(p[0]!), mm(p[1]!), mm(p[2]!)];

/**
 * A deterministic interior point of a room: the first cell (z, then x) of
 * its grid (its own corners + its stairs' rects) inside it and off every
 * stair.
 */
export function samplePoint(house: HouseMap, room: Room): Vec2 {
  const rects = house.stairs.filter((s) => s.from === room.id || s.to === room.id).map((s) => s.rect);
  const xs = breakpoints([...room.poly.map((p) => p[0]), ...rects.flatMap((r) => [r[0], r[2]])]);
  const zs = breakpoints([...room.poly.map((p) => p[1]), ...rects.flatMap((r) => [r[1], r[3]])]);
  for (let j = 0; j + 1 < zs.length; j++) {
    for (let i = 0; i + 1 < xs.length; i++) {
      const c: Vec2 = [(xs[i]! + xs[i + 1]!) / 2, (zs[j]! + zs[j + 1]!) / 2];
      if (pointInPolyStrict(room.poly, c) && !rects.some((r) => pointInRect(r, c))) return c;
    }
  }
  return room.poly[0] ?? [0, 0];
}

function elevationOf(house: HouseMap, room: Room): number {
  return house.floors.find((f) => f.id === room.floor)?.elevation ?? 0;
}

export function locateQueries(house: HouseMap): Vec3[] {
  const out: Vec3[] = [];
  for (const room of house.rooms) {
    const [x, z] = samplePoint(house, room);
    const y = elevationOf(house, room);
    out.push([x, y + 1, z], [x, y + 10, z], [x, y - 0.6, z]);
  }
  for (const p of portals(house)) out.push([p.pos[0], p.pos[1] + 0.1, p.pos[2]]);
  for (const stair of house.stairs) {
    const { low, high } = stairLevels(house, stair);
    const [x0, z0, x1, z1] = stair.rect;
    for (const f of [0, 0.25, 0.5, 0.75, 1]) out.push([(x0 + x1) / 2, low + f * (high - low), (z0 + z1) / 2]);
  }
  for (const t of house.terminals) out.push(t.pos);
  for (const s of house.duck.spots) out.push(s.pos);
  // Inside each solid prop (not standable), and on its top (standable).
  for (const prop of house.props) if (propSolid(prop)) out.push(prop.pos, [prop.pos[0], prop.pos[1] + prop.size[1], prop.pos[2]]);
  out.push(house.spawn.pos, [-100, 0, -100]);
  return out.map(round3);
}

export function routeQueries(house: HouseMap): { from: Vec3; to: Vec3 }[] {
  const samples = house.rooms.map((room): Vec3 => {
    const [x, z] = samplePoint(house, room);
    return [x, elevationOf(house, room), z];
  });
  const out: { from: Vec3; to: Vec3 }[] = [];
  for (let i = 0; i < samples.length; i++) {
    for (let j = 0; j < samples.length; j++) if (i !== j) out.push({ from: samples[i]!, to: samples[j]! });
  }
  for (const s of house.duck.spots) out.push({ from: house.spawn.pos, to: s.pos });
  out.push({ from: house.spawn.pos, to: [-100, 0, -100] });
  return out.map((q) => ({ from: round3(q.from), to: round3(q.to) }));
}

/**
 * The reach queries round each king: feet on 8 bearings (from north,
 * counter-clockwise, 45° apart) at plan radii 0.4 / 1.2 / 1.4 / 1.7 m on his
 * floor, each facing him, then 50° / 70° / 90° off that (to the left) and
 * away; plus one point 1 m east of him at every other floor's elevation.
 */
export function kingQueries(house: HouseMap): { king: string; feet: Vec3; yaw: number }[] {
  const out: { king: string; feet: Vec3; yaw: number }[] = [];
  for (const king of kingProps(house)) {
    const [kx, ky, kz] = king.pos;
    for (let k = 0; k < 8; k++) {
      const a = (k * 45 * Math.PI) / 180;
      for (const r of [0.4, 1.2, 1.4, 1.7]) {
        // Bearing k·45° from north (−z), counter-clockwise (§1 yaw).
        const feet: Vec3 = [kx - Math.sin(a) * r, ky, kz - Math.cos(a) * r];
        const facing = k * 45 + 180;
        for (const off of [0, 50, 70, 90, 180]) out.push({ king: king.id, feet: round3(feet), yaw: wrap(facing + off) });
      }
    }
    for (const f of house.floors) {
      if (Math.abs(f.elevation - ky) < 1e-9) continue;
      out.push({ king: king.id, feet: round3([kx + 1, f.elevation, kz]), yaw: 90 });
    }
  }
  return out;
}

const wrap = (yaw: number): number => (((yaw + 180) % 360) + 360) % 360 - 180;

/** One JSON value per line inside a top-level array. */
export function jsonLines(items: unknown[]): string {
  if (items.length === 0) return "[]\n";
  return `[\n${items.map((i) => `  ${JSON.stringify(i)}`).join(",\n")}\n]\n`;
}

/** Every golden file: file name → contents. */
export function goldenFiles(): Map<string, string> {
  const files = new Map<string, string>();
  for (const { name, house } of goldenMaps()) {
    files.set(`${name}.walls.json`, jsonLines(buildWalls(house)));
    files.set(
      `${name}.routes.json`,
      jsonLines(routeQueries(house).map(({ from, to }) => ({ from, to, path: route(house, from, to).map(round3) }))),
    );
    files.set(
      `${name}.locate.json`,
      jsonLines(
        locateQueries(house).map((p) => {
          const { floor, room } = locate(house, p);
          const h = heightAt(house, [p[0], p[2]], p[1]);
          return { p, floor, room, height: h === null ? null : mm(h), standable: standable(house, p) };
        }),
      ),
    );
    const kings = kingProps(house);
    if (kings.length === 0) continue;
    files.set(
      `${name}.king.json`,
      jsonLines(
        kingQueries(house).map(({ king, feet, yaw }) => {
          const prop = kings.find((k) => k.id === king)!;
          return { king, feet, yaw, reach: kingReach(house, feet, yaw, prop), slack: kingReach(house, feet, yaw, prop, KING_HIT_SLACK) };
        }),
      ),
    );
    const fallen = new Set(kings.map((k) => k.id));
    files.set(
      `${name}.fallen.json`,
      jsonLines(routeQueries(house).map(({ from, to }) => ({ from, to, path: route(house, from, to, { fallen }).map(round3) }))),
    );
  }
  return files;
}
